suppressPackageStartupMessages({library(data.table);library(survival);library(hgu133plus2.db);library(AnnotationDbi)})
root<-".";f<-file.path(root,"data_raw","GSE39582_series_matrix.txt.gz");out<-file.path(root,"results_tables");logd<-file.path(root,"logs")
con<-gzfile(f,"rt");raw<-readLines(con,warn=FALSE);close(con);begin<-which(grepl("!series_matrix_table_begin",raw,fixed=TRUE));end<-which(grepl("!series_matrix_table_end",raw,fixed=TRUE));tab<-fread(text=paste(raw[(begin+1):(end-1)],collapse="\n"),sep="\t",header=TRUE,check.names=FALSE,quote="\"",data.table=TRUE)
sample_line<-raw[grepl("!Sample_geo_accession",raw,fixed=TRUE)][1];ids<-gsub('^"|"$','',strsplit(sub("^!Sample_geo_accession\\t","",sample_line),"\\t")[[1]]);X<-as.matrix(tab[,-1,with=FALSE]);storage.mode(X)<-"numeric";colnames(X)<-ids;probe<-as.character(tab[[1]])
map<-as.data.table(AnnotationDbi::select(hgu133plus2.db,keys=probe,keytype="PROBEID",columns=c("SYMBOL","ENTREZID")));map<-map[SYMBOL%in%c("FASN","SCD")&!is.na(SYMBOL)]
expr<-data.table(sample_id=ids,FASN=NA_real_,SCD=NA_real_);for(g in c("FASN","SCD")){p<-map[SYMBOL==g,PROBEID];ii<-match(p,probe);expr[[g]]<-colMeans(X[ii,,drop=FALSE],na.rm=TRUE)}
chars<-raw[grepl("!Sample_characteristics_ch1",raw,fixed=TRUE)];cm<-lapply(chars,function(z){q<-strsplit(sub("^!Sample_characteristics_ch1\\t","",z),"\\t")[[1]];gsub('^"|"$','',q)});ch<-as.data.table(do.call(rbind,cm));ch<-transpose(ch);ch[,sample_id:=ids]
getv<-function(x,key){z<-as.character(x);ii<-startsWith(tolower(z),tolower(paste0(key,":")));out<-rep(NA_character_,length(z));out[ii]<-sub("^[^:]*:\\s*","",z[ii]);out}
keys<-c("dataset","Sex","age.at.diagnosis (year)","tnm.stage","tnm.t","tnm.n","tnm.m","os.event","os.delay (months)","rfs.event","rfs.delay","mmr.status","kras.mutation","braf.mutation","cit.molecularsubtype")
for(k in keys){j<-which(vapply(ch,function(v)any(startsWith(tolower(v),tolower(paste0(k,":")))),logical(1)));if(length(j))expr[[make.names(k)]]<-getv(ch[[j[1]]],k)}
expr<-expr[dataset!="Non Tumoral"];expr[,FASN:=as.numeric(FASN)];expr[,SCD:=as.numeric(SCD)];expr[,stage:=factor(tnm.stage,levels=c("1","2","3","4"))];expr[,age_num:=as.numeric(age.at.diagnosis..year.)];expr[,os_time:=as.numeric(os.delay..months.)];expr[,os_event_num:=as.integer(os.event)];expr[,FASN_z:=as.numeric(scale(FASN))];expr[,SCD_z:=as.numeric(scale(SCD))];expr[,axis_z:=rowMeans(cbind(FASN_z,SCD_z),na.rm=FALSE)]
fwrite(expr,file.path(out,"GSE39582_FASN_SCD_clinical_matrix.tsv"),sep="\t",na="NA")
stage_test<-function(v){z<-expr[!is.na(stage)&is.finite(get(v)),.(x=get(v),g=stage)];kt<-kruskal.test(x~g,data=z);data.table(dataset="GSE39582",feature=v,n=nrow(z),groups=uniqueN(z$g),p_value=kt$p.value)}
st<-rbind(stage_test("FASN"),stage_test("SCD"),stage_test("axis_z"));st[,p_adj:=p.adjust(p_value,"BH")];fwrite(st,file.path(out,"GSE39582_stage_association_results.tsv"),sep="\t",na="NA")
cox_one<-function(v){z<-expr[is.finite(get(v))&is.finite(os_time)&os_event_num%in%c(0,1)];m<-coxph(as.formula(paste0("Surv(os_time,os_event_num)~",v)),data=z);s<-summary(m);data.table(dataset="GSE39582",feature=v,n=nrow(z),events=sum(z$os_event_num),hr_per_sd=s$coefficients[1,"exp(coef)"],lower95=s$conf.int[1,"lower .95"],upper95=s$conf.int[1,"upper .95"],p_value=s$coefficients[1,"Pr(>|z|)"])}
surv<-rbind(cox_one("FASN_z"),cox_one("SCD_z"),cox_one("axis_z"));surv[,p_adj:=p.adjust(p_value,"BH")];fwrite(surv,file.path(out,"GSE39582_os_cox_results.tsv"),sep="\t",na="NA")
adj_one<-function(v){z<-expr[is.finite(get(v))&is.finite(os_time)&os_event_num%in%c(0,1)&is.finite(age_num)&!is.na(Sex)&!is.na(stage)];z[,Sex:=factor(Sex)];m<-coxph(as.formula(paste0("Surv(os_time,os_event_num)~",v,"+age_num+Sex+stage")),data=z);s<-summary(m);ii<-which(rownames(s$coefficients)==v);data.table(dataset="GSE39582",feature=v,n=nrow(z),events=sum(z$os_event_num),hr_per_sd=s$coefficients[ii,"exp(coef)"],lower95=s$conf.int[ii,"lower .95"],upper95=s$conf.int[ii,"upper .95"],p_value=s$coefficients[ii,"Pr(>|z|)"])}
adj<-rbind(adj_one("FASN_z"),adj_one("SCD_z"),adj_one("axis_z"));adj[,p_adj:=p.adjust(p_value,"BH")];fwrite(adj,file.path(out,"GSE39582_adjusted_os_cox_results.tsv"),sep="\t",na="NA")
qc<-data.table(accession="GSE39582",tumor_samples=nrow(expr),stage_complete=sum(!is.na(expr$stage)),os_complete=sum(is.finite(expr$os_time)&expr$os_event_num%in%c(0,1)),os_events=sum(expr$os_event_num==1,na.rm=TRUE),FASN_detected=sum(is.finite(expr$FASN)),SCD_detected=sum(is.finite(expr$SCD)));fwrite(qc,file.path(out,"GSE39582_validation_qc.tsv"),sep="\t",na="NA")
capture.output(sessionInfo(),file=file.path(logd,"gse39582_validation_sessionInfo.txt"));cat("GSE39582 validation completed; tumor samples",nrow(expr),"\n")
